/* ---------- renderer / scene / lighting ---------- */
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.02;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
$('stage').appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xc3d5e6, 90, 430);
const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 2500);
const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
scene.environmentIntensity = 0.85;

const SUN_DIR = new THREE.Vector3(-0.5, 0.72, 0.42).normalize();
const sun = new THREE.DirectionalLight(0xfff0d8, 3.4);
sun.castShadow = true;
sun.shadow.mapSize.set(4096, 4096);
sun.shadow.bias = -0.00035;
sun.shadow.normalBias = 0.025;
scene.add(sun, sun.target);
function fitSun(T) {
  const S = T / 2 + 7;
  sun.target.position.set(0, 0, 0);
  sun.position.copy(SUN_DIR).multiplyScalar(90);
  const c = sun.shadow.camera;
  c.left = -S; c.right = S; c.top = S * 0.62; c.bottom = -S * 0.62; c.near = 20; c.far = 170;
  c.updateProjectionMatrix();
}

const sky = new THREE.Mesh(new THREE.SphereGeometry(1200, 32, 16), new THREE.ShaderMaterial({
  side: THREE.BackSide, depthWrite: false, fog: false, uniforms: { sunDir: { value: SUN_DIR } },
  vertexShader: 'varying vec3 vP; void main(){ vP=normalize(position); gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }',
  fragmentShader: `varying vec3 vP; uniform vec3 sunDir;
  void main(){ float h=clamp(vP.y,0.,1.); vec3 hor=vec3(.62,.74,.88), zen=vec3(.09,.25,.62);
    vec3 c=mix(hor,zen,pow(h,.5)); float s=max(dot(normalize(vP),sunDir),0.);
    c+=vec3(1.,.82,.55)*(pow(s,900.)*4.+pow(s,10.)*.16); c=mix(c,hor*.85,smoothstep(.02,-.12,vP.y));
    gl_FragColor=vec4(c,1.);
    #include <tonemapping_fragment>
    #include <colorspace_fragment>
  }`
}));
sky.renderOrder = -10; sky.frustumCulled = false;
scene.add(sky);

/* ---------- shared PBR materials ---------- */
const M = {};
function makeMaterials() {
  M.paint = new THREE.MeshPhysicalMaterial({ color: 0xb2101a, metalness: 0.6, roughness: 0.28, clearcoat: 1, clearcoatRoughness: 0.05, envMapIntensity: 1.15 });
  M.paintDark = new THREE.MeshPhysicalMaterial({ color: 0x5a0a10, metalness: 0.5, roughness: 0.5, clearcoat: 0.5, clearcoatRoughness: 0.2 });
  M.trim = new THREE.MeshStandardMaterial({ color: 0x14161a, roughness: 0.5, metalness: 0.25 });
  M.dark = new THREE.MeshStandardMaterial({ color: 0x08090b, roughness: 0.92, metalness: 0.1 });
  M.chrome = new THREE.MeshStandardMaterial({ color: 0xe0e4ea, metalness: 1, roughness: 0.14 });
  M.tire = new THREE.MeshStandardMaterial({ color: 0x111214, roughness: 0.93, metalness: 0 });
  M.rim = new THREE.MeshStandardMaterial({ color: 0xc9ccd3, metalness: 1, roughness: 0.2 });
  M.glass = new THREE.MeshPhysicalMaterial({ color: 0x8fb4c6, metalness: 0, roughness: 0.02, transparent: true, opacity: 0.34,
    clearcoat: 1, clearcoatRoughness: 0, ior: 1.52, envMapIntensity: 2.4, side: THREE.DoubleSide, depthWrite: false });
  M.head = new THREE.MeshStandardMaterial({ color: 0xfff4d0, emissive: 0xffe9b0, emissiveIntensity: 1.6, roughness: 0.15, metalness: 0.2 });
  M.tail = new THREE.MeshStandardMaterial({ color: 0x8a0508, emissive: 0xff1010, emissiveIntensity: 0.9, roughness: 0.25 });
  M.interior = new THREE.MeshStandardMaterial({ color: 0x24262b, roughness: 0.9 });
  M.seat = new THREE.MeshStandardMaterial({ color: 0x3a3d44, roughness: 0.85 });
  M.brick = new THREE.MeshStandardMaterial({ map: TEX.brick, bumpMap: TEX.brick, bumpScale: 1.6, roughness: 0.96, metalness: 0 });
  M.asphalt = new THREE.MeshStandardMaterial({ map: TEX.asphalt, bumpMap: TEX.asphalt, bumpScale: 1.4, roughness: 0.93, metalness: 0, color: 0xd8d8d8 });
  M.pad = new THREE.MeshStandardMaterial({ map: TEX.asphalt, color: 0x9a9da3, roughness: 0.9 });
  M.gravel = new THREE.MeshStandardMaterial({ map: TEX.gravel, bumpMap: TEX.gravel, bumpScale: 2, roughness: 1 });
  M.grass = new THREE.MeshStandardMaterial({ map: TEX.grass, bumpMap: TEX.grass, bumpScale: 1, roughness: 1 });
  M.line = new THREE.MeshStandardMaterial({ color: 0xf1f1ec, roughness: 0.6, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
  M.start = new THREE.MeshStandardMaterial({ map: TEX.start, roughness: 0.6, polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2 });
  M.vcol = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.75, metalness: 0.05 });
  M.concrete = new THREE.MeshStandardMaterial({ color: 0xa5a6a2, roughness: 0.95 });
  M.pole = new THREE.MeshStandardMaterial({ color: 0x3b4048, roughness: 0.5, metalness: 0.7 });
  M.lamp = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xfff1cf, emissiveIntensity: 2.4 });
  M.hill = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 1, flatShading: true });
  M.leaf = new THREE.MeshStandardMaterial({ color: 0x2f5a2c, roughness: 1 });
  M.trunk = new THREE.MeshStandardMaterial({ color: 0x4b3421, roughness: 1 });
  M.shardShadowless = null;
}

/* ---------- static environment: track, curbs, shoulders, barriers, lights ---------- */
function planeGeo(w, d, tile) {
  const g = new THREE.PlaneGeometry(w, d); g.rotateX(-Math.PI / 2);
  const uv = g.attributes.uv; for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) * w / tile, uv.getY(i) * d / tile);
  return g;
}
function flat(cx, cz, sx, sz, y = 0.004) { return new THREE.PlaneGeometry(sx, sz).rotateX(-Math.PI / 2).translate(cx, y, cz); }
function colored(geo, c) {
  const n = geo.attributes.position.count, a = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { a[i * 3] = c.r; a[i * 3 + 1] = c.g; a[i * 3 + 2] = c.b; }
  geo.setAttribute('color', new THREE.BufferAttribute(a, 3)); return geo;
}
const noUV = g => g.index ? g.toNonIndexed() : g;
