const CG_GROUND = CG(1, 2 | 4 | 8), CG_BRICK = CG(2, 1 | 2 | 4 | 8), CG_CAR = CG(4, 1 | 2 | 8), CG_DEBRIS = CG(8, 1 | 2 | 4 | 8);
