  const wallX = T / 2 - 7, wallFront = wallX - S.depth * S.bd / 2;
  const startX = Math.min(-T / 2 + 3.2 + L / 2, wallFront - L / 2 - 3);
  const world = new RAPIER.World({ x: 0, y: -S.gravity, z: 0 });
